exception handling.syntax:
try:
    result = 10 / 0
except ZeroDivisionError:
    print('Cannot divide by zero!')
finally:
    print('Operation complete')

class.syntax:
class Car:
    def __init__(self, color):
        self.color = color

    def honk(self):
        return 'Honk! Honk!'

decorator.syntax:
def my_decorator(func):
    def wrapper():
        print('Before')
        func()
        print('After')
    return wrapper

@my_decorator
def say_hello():
    print('Hello!')

generator.syntax:
def count_up(n):
    i = 0
    while i < n:
        yield i
        i += 1

for num in count_up(5):
    print(num)

